  <script>
    const filterButtons = document.querySelectorAll('[data-filter]');
    const productCards = document.querySelectorAll('#productGrid .product-card');

    filterButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const filter = button.dataset.filter;

        filterButtons.forEach((btn) => btn.classList.toggle('active', btn === button));

        productCards.forEach((card) => {
          const match = filter === 'all' || card.dataset.category === filter;
          card.classList.toggle('is-hidden', !match);
        });
      });
    });

    const endDate = new Date(Date.now() + (12 * 24 * 60 * 60 * 1000) + (8 * 60 * 60 * 1000) + (24 * 60 * 1000) + (5 * 1000));
    const clock = {
      days: document.getElementById('days'),
      hours: document.getElementById('hours'),
      minutes: document.getElementById('minutes'),
      seconds: document.getElementById('seconds'),
    };

    function pad(value) {
      return String(value).padStart(2, '0');
    }

    function tick() {
      const diff = Math.max(0, endDate - new Date());
      const totalSeconds = Math.floor(diff / 1000);
      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      clock.days.textContent = String(days);
      clock.hours.textContent = pad(hours);
      clock.minutes.textContent = pad(minutes);
      clock.seconds.textContent = pad(seconds);
    }

    tick();
    setInterval(tick, 1000);
  </script>
